<script lang="ts">
  import { onMount,tick } from 'svelte';
  import { invoke } from '@tauri-apps/api/core';
  import { eventTime,sameSelection } from './calendar';
  import type { CalendarSnapshot,CalendarPreferences,CalendarAction,CalendarFlow } from './calendar';
  let snapshot=$state<CalendarSnapshot|null>(null),preferences=$state<CalendarPreferences|null>(null);
  let selected=$state<string[]>([]),reminder=$state(10),filter=$state(''),visible=$state(100);
  let busy=$state(false),busyLabel=$state(''),error=$state(''),message=$state(''),confirmation=$state<{action:CalendarAction;message:string}|null>(null);
  let flow=$state<CalendarFlow|null>(null),watching=$state(true);
  let provider=$state('google'),account=$state('google'),client=$state(''),secret=$state(''),tenant=$state('common');
  let deleteLocal=$state<Record<string,boolean>>({});
  let refreshing=$state(false);
  let alive=true,polling=false,revision=0;
  let dirty=$derived(!!preferences&&(!sameSelection(selected,preferences.account.calendar_ids)||reminder!==preferences.account.reminder_minutes));
  let filtered=$derived(preferences?.calendars.filter(calendar=>(calendar.name+' '+calendar.id).toLowerCase().includes(filter.toLowerCase()))??[]);
  let stale=$derived(!!preferences&&!!snapshot&&snapshot.accounts.some(account=>account.account_id===preferences?.account.account_id&&(!sameSelection(account.calendar_ids,preferences.account.calendar_ids)||account.reminder_minutes!==preferences.account.reminder_minutes)));
  $effect(()=>{if(confirmation)void tick().then(()=>document.getElementById('calendar-confirmation')?.focus());});
  async function refresh(clear=true){if(busy||refreshing)return;refreshing=true;const token=revision;try{const next=await invoke<CalendarSnapshot>('get_calendar');if(alive&&token===revision){snapshot=next;if(!flow||flow.flow_id===next.flow?.flow_id)flow=next.flow;if(clear)error='';}}catch(cause){if(alive&&token===revision)error=String(cause);}finally{refreshing=false;}}
  async function discover(id:string){if(busy)return;revision++;busy=true;busyLabel='Loading provider calendars…';error='';message='';try{const next=await invoke<CalendarPreferences>('discover_calendars',{accountId:id});if(alive){preferences=next;selected=[...next.account.calendar_ids];reminder=next.account.reminder_minutes;filter='';visible=100;await tick();document.getElementById('calendar-management')?.focus();}}catch(cause){if(alive)error=String(cause);}finally{if(alive){busy=false;busyLabel='';}}}
  async function apply(action:CalendarAction){if(busy)return;revision++;busy=true;busyLabel='Updating calendar account…';error='';message='';confirmation=null;try{const result=await invoke<{message:string}>('apply_calendar',{action});if(alive){message=result.message;if(action.type==='preferences'&&preferences){preferences.account.calendar_ids=[...selected];preferences.account.reminder_minutes=reminder;}if(action.type==='disconnect'&&preferences?.account.account_id===action.account_id)preferences=null;}}catch(cause){if(alive)error=String(cause);}finally{if(alive){busy=false;busyLabel='';void refresh(false);}}}
  function save(){if(!preferences)return;const action:CalendarAction={type:'preferences',account_id:preferences.account.account_id,expected_calendar_ids:[...preferences.account.calendar_ids],expected_reminder_minutes:preferences.account.reminder_minutes,calendar_ids:[...selected],reminder_minutes:reminder};if(preferences.account.calendar_ids.some(id=>!selected.includes(id)))confirmation={action,message:'Calendars removed from sync will also have their cached events removed locally. Events at your provider are unchanged.'};else void apply(action);}
  async function start(){if(busy)return;revision++;busy=true;busyLabel='Starting browser sign-in…';error='';message='';const clientSecret=secret;secret='';try{const next=await invoke<CalendarFlow>('connect_calendar',{input:{provider,account_id:account.trim(),client_id:client.trim(),client_secret:provider==='google'&&clientSecret?clientSecret:null,tenant:provider==='microsoft'?tenant.trim():null}});if(alive){flow=next;watching=true;if(next.browser_available)await invoke('open_calendar_browser',{flowId:next.flow_id});}}catch(cause){if(alive)error=String(cause);}finally{if(alive){busy=false;busyLabel='';}}}
  async function browser(){if(!flow)return;busy=true;error='';try{await invoke('open_calendar_browser',{flowId:flow.flow_id});}catch(cause){error=String(cause);}finally{busy=false;}}
  async function poll(){if(!alive||!watching||busy||polling||!flow||flow.state!=='waiting_for_browser')return;polling=true;const id=flow.flow_id;try{const next=await invoke<CalendarFlow>('calendar_sign_in_status',{flowId:id});if(alive&&flow?.flow_id===id){flow=next;if(next.state!=='waiting_for_browser')void refresh(false);}}catch(cause){if(alive)error=String(cause);}finally{polling=false;}}
  onMount(()=>{void refresh();const timer=window.setInterval(()=>void poll(),2000);const status=window.setInterval(()=>void refresh(false),30000);return()=>{alive=false;revision++;secret='';window.clearInterval(timer);window.clearInterval(status);};});
</script>
<div class="page-heading"><div><div class="eyebrow">MAKE ROOM FOR YOUR DAY</div><h1>Calendar</h1><p>Your connected calendars, upcoming events, and local reminders.</p></div><button class="quiet" disabled={busy||refreshing} onclick={()=>refresh()}>Refresh calendar</button></div>
{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if message}<div class="notice success" role="status">{message}</div>{/if}{#if busyLabel}<div class="notice pending" role="status">{busyLabel}</div>{/if}
{#if confirmation}<section id="calendar-confirmation" tabindex="-1" class="calendar-prompt" role="group" aria-label="Confirm calendar change"><h2>Confirm calendar change</h2><p>{confirmation.message}</p><button class="quiet" onclick={()=>confirmation=null}>Keep current settings</button><button class="quiet" onclick={()=>{if(confirmation)void apply(confirmation.action);}}>Confirm calendar change</button></section>{/if}
{#if snapshot}
  {#if snapshot.paused}<div class="notice pending" role="status">Calendar connectors are paused. Cached events remain available; sync will resume when connectors are enabled.</div>{/if}
  <section class="section"><h2>Next 7 days</h2><p class="description">Cached events · times use your local time zone. Event editing is available in the Calendar application.</p><div class="settings-card">{#each snapshot.events as event}<div class="setting-row event-row"><div><strong>{event.title||'Untitled event'}</strong><p>{eventTime(event)}</p><p>{event.provider} · {event.account_id}</p></div><span class="event-badge">{event.all_day?'ALL DAY':'EVENT'}</span></div>{:else}<div class="setting-row"><p>No cached events for the next 7 days.</p></div>{/each}</div></section>
  <section class="section"><h2>Connected accounts</h2><div class="settings-card">{#each snapshot.accounts as account}<div class="account-row"><div class="account-heading"><div><strong>{account.account_id}</strong><p>{account.provider} · {account.connected?'Connected':'Disconnected'} · {account.cached_events} cached events</p><p>{account.sync_state.replaceAll('_',' ')}{account.last_sync_at_unix?' · Last sync '+new Date(account.last_sync_at_unix*1000).toLocaleString():''}</p>{#if account.last_error}<p role="status">{account.last_error}</p>{/if}</div><div class="account-actions"><button class="quiet" disabled={busy||!account.connected} aria-label={`Manage calendars for ${account.account_id}`} onclick={()=>discover(account.account_id)}>Calendars</button><button class="quiet" disabled={busy||!account.connected||!account.enabled} aria-label={`Sync ${account.account_id}`} onclick={()=>apply({type:'sync',account_id:account.account_id})}>Sync now</button></div></div><div class="disconnect-row"><label><input type="checkbox" bind:checked={deleteLocal[account.account_id]} disabled={busy} /> Delete local data when disconnecting</label><button class="quiet" disabled={busy} aria-label={`Disconnect calendar ${account.account_id}`} onclick={()=>confirmation={action:{type:'disconnect',account_id:account.account_id,delete_local_data:!!deleteLocal[account.account_id]},message:deleteLocal[account.account_id]?`Disconnect ${account.account_id} and delete its local cached events? Provider events are unchanged.`:`Disconnect ${account.account_id}? Saved credentials will be removed; local cached events will be retained.`}}>Disconnect</button></div></div>{:else}<div class="setting-row"><p>No calendar accounts connected. Add an account below.</p></div>{/each}</div><p class="footnote">Sync may require calendar consent in AI Console. Queuing a sync does not mean it has finished.</p></section>
{/if}
{#if preferences}<section id="calendar-management" tabindex="-1" class="section"><div class="section-heading"><h2>Calendars · {preferences.account.account_id}</h2><button class="quiet" disabled={busy} onclick={()=>discover(preferences!.account.account_id)}>Reload calendars</button></div>{#if stale}<div class="notice pending" role="status">Preferences changed in another client. Reload calendars before applying.</div>{/if}<fieldset disabled={busy||!!confirmation}><legend class="sr-only">Calendar selection and reminders</legend><div class="settings-card"><div class="setting-row"><div><label for="calendar-reminder">Reminder before each event</label><p>Notifications are managed locally by FocalDesk.</p></div><select id="calendar-reminder" bind:value={reminder}>{#each [[0,'Off'],[5,'5 minutes'],[10,'10 minutes'],[15,'15 minutes'],[30,'30 minutes'],[60,'1 hour']] as [value,label]}<option {value}>{label}</option>{/each}</select></div><div class="setting-row"><label for="calendar-filter">Find a calendar</label><input id="calendar-filter" type="search" bind:value={filter} oninput={()=>visible=100} /></div>{#each filtered.slice(0,visible) as calendar,index}<div class="setting-row"><div><label for={`calendar-choice-${index}`}>{calendar.name}</label><p>{calendar.primary?'Primary calendar':calendar.id}</p></div><input id={`calendar-choice-${index}`} class="switch" type="checkbox" role="switch" checked={selected.includes(calendar.id)} disabled={!selected.includes(calendar.id)&&selected.length>=32} onchange={event=>{selected=event.currentTarget.checked?[...selected,calendar.id]:selected.filter(id=>id!==calendar.id);}} /></div>{:else}<div class="setting-row"><p>No calendars match your search.</p></div>{/each}</div></fieldset>{#if filtered.length>visible}<button class="quiet" onclick={()=>visible+=100}>Show more calendars</button>{/if}<div class="selection-actions"><span>{selected.length} selected · Keep 1–32 calendars selected.</span><button class="quiet" disabled={busy||!dirty} onclick={()=>{if(preferences){selected=[...preferences.account.calendar_ids];reminder=preferences.account.reminder_minutes;}}}>Discard calendar changes</button><button class="primary" disabled={busy||!dirty||!selected.length||stale} onclick={save}>Save calendar preferences</button></div></section>{/if}
{#if flow}<section class="calendar-prompt" role="status"><h2>{flow.state==='connected'?'Account connected':flow.state==='error'?'Sign-in ended':'Browser sign-in'}</h2><p>{flow.account_id} · {flow.provider}</p><p>{flow.message}</p>{#if flow.user_code}<p class="user-code">Browser code: {flow.user_code}</p>{/if}{#if flow.state==='waiting_for_browser'}<div class="account-actions"><button class="quiet" disabled={busy||!flow.browser_available} onclick={browser}>Open sign-in page</button><button class="quiet" onclick={()=>watching=!watching}>{watching?'Stop waiting':'Resume waiting'}</button></div><p>Stopping waiting or leaving this page stops status checks. Browser sign-in can still finish in the background until it expires.</p>{/if}</section>{/if}
<section class="section"><h2>Add a calendar account</h2><p class="description">Sign in with Google or Microsoft in your browser. Your provider’s consent screen explains the requested calendar read/write access. This page reads cached events and manages connections.</p><fieldset disabled={busy}><legend class="sr-only">Calendar account sign-in</legend><div class="settings-card"><div class="setting-row"><label for="calendar-provider">Provider</label><select id="calendar-provider" bind:value={provider} onchange={()=>secret=''}><option value="google">Google Calendar</option><option value="microsoft">Microsoft 365</option></select></div><div class="setting-row"><div><label for="calendar-account">Account name</label><p>A local label using letters, numbers, dashes, or underscores.</p></div><input id="calendar-account" type="text" maxlength="64" bind:value={account} autocomplete="off" /></div><div class="setting-row"><div><label for="calendar-client">OAuth application client ID</label><p>Use the desktop application ID registered with your provider.</p></div><input id="calendar-client" type="text" maxlength="256" bind:value={client} autocomplete="off" /></div>{#if provider==='google'}<div class="setting-row"><div><label for="calendar-secret">Application client secret (optional)</label><p>Only if your Google application requires one. Cleared from this form after submission.</p></div><input id="calendar-secret" type="password" maxlength="4096" bind:value={secret} autocomplete="off" /></div>{:else}<div class="setting-row"><div><label for="calendar-tenant">Microsoft tenant</label><p>Use common, your tenant ID, or your organization’s domain.</p></div><input id="calendar-tenant" type="text" maxlength="128" bind:value={tenant} /></div>{/if}<div class="setting-row"><p>OAuth tokens stay with the Rust services and secrets broker.</p><button class="primary" disabled={busy||!account.trim()||!client.trim()||flow?.state==='waiting_for_browser'} onclick={start}>Start browser sign-in</button></div></div></fieldset></section>
<style>
  fieldset{border:0;margin:0;padding:0;min-width:0}strong{font-size:13px;font-weight:600}.description,.footnote{font-size:12px;color:var(--fd-text-muted);line-height:1.8;margin:10px 0 16px}.account-row{padding:20px;border-bottom:1px solid var(--fd-border)}.account-row:last-child{border-bottom:0}.account-heading{display:flex;justify-content:space-between;gap:15px;align-items:center}.account-row p{font-size:11px;color:var(--fd-text-muted);line-height:1.8;margin-top:6px}.account-actions{display:flex;gap:8px;flex-wrap:wrap}.disconnect-row{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:16px}.disconnect-row label{font-size:11px;color:var(--fd-text-muted)}input,select{font:inherit;font-size:12px;color:var(--fd-text);background:var(--fd-surface);border:1px solid var(--fd-border);border-radius:7px;padding:9px 11px;max-width:260px}input[type=checkbox]{accent-color:var(--fd-accent)}.primary{background:var(--fd-accent);color:white;padding:10px 14px;border-radius:8px;font-size:12px}.calendar-prompt{border:1px solid var(--fd-border);background:var(--fd-surface);padding:22px;border-radius:var(--fd-radius);margin:22px 0}.calendar-prompt p{font-size:12px;color:var(--fd-text-muted);line-height:1.8;margin:12px 0}.calendar-prompt>button{margin-right:8px}.user-code{font:16px ui-monospace,monospace!important;color:var(--fd-accent)!important}.event-badge{font-size:9px;color:var(--fd-text-muted);border:1px solid var(--fd-border);padding:5px 8px;border-radius:6px;white-space:nowrap}.pending{background:var(--fd-accent-soft);color:var(--fd-text-muted);line-height:1.8}.selection-actions{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:18px 0}.selection-actions>span{font-size:11px;color:var(--fd-text-muted);margin-right:auto}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}@media(max-width:900px){.account-heading,.disconnect-row{align-items:flex-start;flex-direction:column}.setting-row input[type=text],.setting-row input[type=password]{width:100%;max-width:260px}}
</style>
